/// <summary>Contribution is a convention's addition to one project.</summary>
public sealed record Contribution : IProtocolValue<Contribution>
{
    /// <summary>Tasks are new tasks. A task the project already has is kept as it is.</summary>
    public IReadOnlyDictionary<string, ProjectTask> Tasks { get; init; } = new Dictionary<string, ProjectTask>();

    /// <summary>Replace are tasks that replace the project's task of the same name, or are added when it has none.</summary>
    public IReadOnlyDictionary<string, ProjectTask> Replace { get; init; } = new Dictionary<string, ProjectTask>();

    /// <summary>DependsOn adds dependencies to tasks the project already has, by task name ({"lint": ["slice-check"]}).</summary>
    public IReadOnlyDictionary<string, IReadOnlyList<string>> DependsOn { get; init; } = new Dictionary<string, IReadOnlyList<string>>();

    /// <summary>Release is how the project's release files are made, for a project that releases through GitHub releases and leaves them out of its smith.toml [projects.&lt;name&gt;.release] table; what the table sets wins.</summary>
    public ReleaseDefaults? Release { get; init; }

    /// <summary>Facts are the plugin's default facts for the project: typed values under namespaced keys ({"source.roots": ["src"]}) that other settings and plugins read through the merged Project.Facts. They are the lowest scope: a [facts] table in smith.toml wins over them, and two plugins that publish different values for one key are an error that names both.</summary>
    public JsonMap Facts { get; init; } = new();

    /// <inheritdoc />
    public static Contribution Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new Contribution
        {
            Tasks = MapOf(Member(map, "tasks"), Join(path, "tasks"), ProjectTask.Read),
            Replace = MapOf(Member(map, "replace"), Join(path, "replace"), ProjectTask.Read),
            DependsOn = MapOf(Member(map, "dependsOn"), Join(path, "dependsOn"), (value1, path1) => ListOf(value1, path1, StringValue)),
            Release = OptionalStruct<ReleaseDefaults>(Member(map, "release"), Join(path, "release")),
            Facts = ObjectOf(Member(map, "facts"), Join(path, "facts")),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        if (Tasks is { Count: > 0 })
        {
            writer.Property("tasks");
            MessageWritingAlgorithm.Map(writer, Tasks, (builder1, member1) => member1.Write(builder1));
        }
        if (Replace is { Count: > 0 })
        {
            writer.Property("replace");
            MessageWritingAlgorithm.Map(writer, Replace, (builder1, member1) => member1.Write(builder1));
        }
        if (DependsOn is { Count: > 0 })
        {
            writer.Property("dependsOn");
            MessageWritingAlgorithm.Map(writer, DependsOn, (builder1, member1) => MessageWritingAlgorithm.List(builder1, member1, (builder2, item2) => builder2.String(item2)));
        }
        if (Release is not null)
        {
            writer.Property("release");
            Release.Write(writer);
        }
        if (Facts is { Count: > 0 })
        {
            writer.Property("facts");
            writer.Any(Facts);
        }
        writer.EndObject();
    }
}

