/// <summary>InitializeResult tells the host who the plugin is and what it can do.</summary>
public sealed record InitializeResult : IProtocolValue<InitializeResult>
{
    /// <summary>ProtocolVersion is the version the plugin chose from the host's list.</summary>
    public long ProtocolVersion { get; init; }

    /// <summary>The <c>plugin</c> member of <c>InitializeResult</c>.</summary>
    public required Peer Plugin { get; init; }

    /// <summary>The <c>kind</c> member of <c>InitializeResult</c>.</summary>
    public required PluginKind Kind { get; init; }

    /// <summary>The <c>capabilities</c> member of <c>InitializeResult</c>.</summary>
    public required Capabilities Capabilities { get; init; }

    /// <summary>Concurrency is how many requests the plugin can work on at the same time; the host never has more in flight. Absent or 0 means 1, which is what every plugin that says nothing does: the host sends the next request only after the previous one is answered. N above 1 allows that many, and ConcurrencyUnlimited (-1) leaves the number to the host. Any other negative value is invalid and read as 1.</summary>
    public long Concurrency { get; init; }

    /// <summary>Languages are the values a user passes to --lang to reach this plugin.</summary>
    public IReadOnlyList<string> Languages { get; init; } = [];

    /// <summary>Manifests are file base names (package.json, go.mod), or patterns of them (*.csproj), whose presence in a directory may make it a project of this plugin.</summary>
    public IReadOnlyList<string> Manifests { get; init; } = [];

    /// <summary>Roles are the levels the plugin can be chosen for in a project's make-up (a stack, a recipe). Empty means the default of its kind (see DefaultRoles). A role is a level: there is no separate level field, because one plugin can play several (a scaffold that is also a toolchain).</summary>
    public IReadOnlyList<Role> Roles { get; init; } = [];

    /// <summary>Provides are the slots a toolchain plugin fills: the task names it owns ("test" for a test runner). A slot is exclusive: two plugins of one project may not provide the same task.</summary>
    public IReadOnlyList<string> Provides { get; init; } = [];

    /// <summary>Requires are plugins that must also be in the project for this one to work: a Node toolchain requires the node language plugin.</summary>
    public IReadOnlyList<PluginRef> Requires { get; init; } = [];

    /// <summary>Conflicts are plugins that must not be in the same project.</summary>
    public IReadOnlyList<PluginRef> Conflicts { get; init; } = [];

    /// <summary>Stacks are ready-made stacks the plugin publishes.</summary>
    public IReadOnlyList<Stack> Stacks { get; init; } = [];

    /// <summary>Kinds are the project kinds the plugin can scaffold with generate. Absent or empty means all three (app, lib and package): what every plugin that says nothing does. A plugin that scaffolds only some, such as an app, lists them, so the host offers and the conformance suite asks for just those.</summary>
    public IReadOnlyList<ProjectKind> Kinds { get; init; } = [];

    /// <summary>Follows are the shape keys (see Project.Shape) the plugin applies when it generates a project with GenerateParams.Shape. Where siblings split on a key, the host asks the person only for a key that a plugin of the stack follows. Absent means the plugin follows none.</summary>
    public IReadOnlyList<string> Follows { get; init; } = [];

    /// <summary>Choices are the options on an axis (framework, test, style) the plugin owns. The host lists them (smith choices) and checks a selection of them (smith add --with). Absent means the plugin owns none.</summary>
    public IReadOnlyList<Choice> Choices { get; init; } = [];

    /// <inheritdoc />
    public static InitializeResult Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new InitializeResult
        {
            ProtocolVersion = IntegerValue(Member(map, "protocolVersion"), Join(path, "protocolVersion")),
            Plugin = Peer.Read(Member(map, "plugin"), Join(path, "plugin")),
            Kind = PluginKind.Read(Member(map, "kind"), Join(path, "kind")),
            Capabilities = Capabilities.Read(Member(map, "capabilities"), Join(path, "capabilities")),
            Concurrency = IntegerValue(Member(map, "concurrency"), Join(path, "concurrency")),
            Languages = ListOf(Member(map, "languages"), Join(path, "languages"), StringValue),
            Manifests = ListOf(Member(map, "manifests"), Join(path, "manifests"), StringValue),
            Roles = ListOf(Member(map, "roles"), Join(path, "roles"), Role.Read),
            Provides = ListOf(Member(map, "provides"), Join(path, "provides"), StringValue),
            Requires = ListOf(Member(map, "requires"), Join(path, "requires"), PluginRef.Read),
            Conflicts = ListOf(Member(map, "conflicts"), Join(path, "conflicts"), PluginRef.Read),
            Stacks = ListOf(Member(map, "stacks"), Join(path, "stacks"), Stack.Read),
            Kinds = ListOf(Member(map, "kinds"), Join(path, "kinds"), ProjectKind.Read),
            Follows = ListOf(Member(map, "follows"), Join(path, "follows"), StringValue),
            Choices = ListOf(Member(map, "choices"), Join(path, "choices"), Choice.Read),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        writer.Property("protocolVersion");
        writer.Integer(ProtocolVersion);
        writer.Property("plugin");
        Plugin.Write(writer);
        writer.Property("kind");
        Kind.Write(writer);
        writer.Property("capabilities");
        Capabilities.Write(writer);
        if (Concurrency != 0)
        {
            writer.Property("concurrency");
            writer.Integer(Concurrency);
        }
        if (Languages is { Count: > 0 })
        {
            writer.Property("languages");
            MessageWritingAlgorithm.List(writer, Languages, (builder1, item1) => builder1.String(item1));
        }
        if (Manifests is { Count: > 0 })
        {
            writer.Property("manifests");
            MessageWritingAlgorithm.List(writer, Manifests, (builder1, item1) => builder1.String(item1));
        }
        if (Roles is { Count: > 0 })
        {
            writer.Property("roles");
            MessageWritingAlgorithm.List(writer, Roles, (builder1, item1) => item1.Write(builder1));
        }
        if (Provides is { Count: > 0 })
        {
            writer.Property("provides");
            MessageWritingAlgorithm.List(writer, Provides, (builder1, item1) => builder1.String(item1));
        }
        if (Requires is { Count: > 0 })
        {
            writer.Property("requires");
            MessageWritingAlgorithm.List(writer, Requires, (builder1, item1) => item1.Write(builder1));
        }
        if (Conflicts is { Count: > 0 })
        {
            writer.Property("conflicts");
            MessageWritingAlgorithm.List(writer, Conflicts, (builder1, item1) => item1.Write(builder1));
        }
        if (Stacks is { Count: > 0 })
        {
            writer.Property("stacks");
            MessageWritingAlgorithm.List(writer, Stacks, (builder1, item1) => item1.Write(builder1));
        }
        if (Kinds is { Count: > 0 })
        {
            writer.Property("kinds");
            MessageWritingAlgorithm.List(writer, Kinds, (builder1, item1) => item1.Write(builder1));
        }
        if (Follows is { Count: > 0 })
        {
            writer.Property("follows");
            MessageWritingAlgorithm.List(writer, Follows, (builder1, item1) => builder1.String(item1));
        }
        if (Choices is { Count: > 0 })
        {
            writer.Property("choices");
            MessageWritingAlgorithm.List(writer, Choices, (builder1, item1) => item1.Write(builder1));
        }
        writer.EndObject();
    }
