/// <remarks>
/// <para>A string, not a closed set: a newer protocol may add values, and one that is not listed here is kept as it came.</para>
/// </remarks>
public readonly record struct PluginKind : IProtocolValue<PluginKind>
{
    private readonly string? _value;

    /// <summary>A plugin kind given as text.</summary>
    /// <param name="value">The text.</param>
    public PluginKind(string value)
    {
        _value = value;
    }

    /// <summary>The text of the value: empty for the default one.</summary>
    public string Value => _value ?? string.Empty;

    /// <summary>Whether the value is empty, which is what an absent member reads as.</summary>
    public bool IsEmpty => Value.Length == 0;

    /// <summary>The value <c>language</c>.</summary>
    public static PluginKind Language { get; } = new("language");

    /// <summary>The value <c>convention</c>.</summary>
    public static PluginKind Convention { get; } = new("convention");

    /// <summary>A PluginKind from text.</summary>
    /// <param name="value">The text.</param>
    public static implicit operator PluginKind(string value) => new(value);

    /// <summary>The text of a PluginKind.</summary>
    /// <param name="value">The value.</param>
    public static implicit operator string(PluginKind value) => value.Value;

    /// <inheritdoc />
    public static PluginKind Read(JsonAny? value, string path) => new(MessageReadingAlgorithm.StringValue(value, path));

    /// <inheritdoc />
    public void Write(JsonBuilder writer) => writer.String(Value);

    /// <summary>Whether another value has the same text.</summary>
    /// <param name="other">The other value.</param>
    /// <returns>Whether they are equal.</returns>
    public bool Equals(PluginKind other) => string.Equals(Value, other.Value, StringComparison.Ordinal);

    /// <inheritdoc />
    public override int GetHashCode() => StringComparer.Ordinal.GetHashCode(Value);

    /// <inheritdoc />
    public override string ToString() => Value;
}

/// <summary>PluginRef names the plugins a requirement or a conflict is about. Every field set must match; at least one must be set.</summary>
public sealed record PluginRef : IProtocolValue<PluginRef>
{
    /// <summary>Level is the role the plugin is chosen for in the project.</summary>
    public Role Level { get; init; }

    /// <summary>Name is the plugin's name, or for a language plugin one of its languages ("node", "javascript").</summary>
    public string Name { get; init; } = string.Empty;

    /// <summary>Slot is a task the plugin provides ("test").</summary>
    public string Slot { get; init; } = string.Empty;

    /// <inheritdoc />
    public static PluginRef Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new PluginRef
        {
            Level = Role.Read(Member(map, "level"), Join(path, "level")),
            Name = StringValue(Member(map, "name"), Join(path, "name")),
            Slot = StringValue(Member(map, "slot"), Join(path, "slot")),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        if (!Level.IsEmpty)
        {
            writer.Property("level");
            Level.Write(writer);
        }
        if (Name.Length > 0)
        {
            writer.Property("name");
            writer.String(Name);
        }
        if (Slot.Length > 0)
        {
            writer.Property("slot");
            writer.String(Slot);
        }
        writer.EndObject();
    }
}

/// <summary>Project is one unit of the monorepo as a plugin sees it.</summary>
public sealed record Project : IProtocolValue<Project>
{
    /// <summary>Name is unique across the workspace; it is what users type.</summary>
    public required string Name { get; init; }

    /// <summary>Root is the workspace-relative directory, forward slashes.</summary>
    public required string Root { get; init; }

    /// <summary>The <c>language</c> member of <c>Project</c>.</summary>
    public required string Language { get; init; }

    /// <summary>The <c>kind</c> member of <c>Project</c>.</summary>
    public required ProjectKind Kind { get; init; }

    /// <summary>Exports are the identifiers other projects import this one by: an npm package name, a Go module path, a Python import name.</summary>
    public IReadOnlyList<string> Exports { get; init; } = [];

    /// <summary>Imports are identifiers this project's sources import. The host keeps the ones another project exports and turns them into graph edges.</summary>
    public IReadOnlyList<string> Imports { get; init; } = [];

    /// <summary>Version is the version recorded in the manifest, if it has one.</summary>
    public string Version { get; init; } = string.Empty;

    /// <summary>Toolchain is the version of the compiler or runtime the project's tasks run with ("node 20.11.0", "go 1.23.4"), as the plugin probed it. It goes into every task's cache key, so a result from another version is a miss. Empty when the plugin cannot tell, and then it is left out.</summary>
    public string Toolchain { get; init; } = string.Empty;

    /// <summary>PublishTo is where a package publishes, when its manifest says: "pub.dev" for the public registry that takes a package only from a run on its tag (so a release does not publish it itself), "none" for a package that is never published, or a repository URL. Empty when the plugin does not say.</summary>
    public string PublishTo { get; init; } = string.Empty;

    /// <summary>Description is the one-line description the manifest records (package.json description, pyproject.toml project.description, the pom's &lt;description&gt;), if it has one. Conventions use it where a registry asks for a summary.</summary>
    public string Description { get; init; } = string.Empty;

    /// <summary>TagPrefix overrides the release tag prefix; empty means "&lt;name&gt;@". Go modules use "&lt;root&gt;/v" so <c>go get</c> can resolve the tag.</summary>
    public string TagPrefix { get; init; } = string.Empty;

    /// <summary>The <c>tasks</c> member of <c>Project</c>.</summary>
    public IReadOnlyDictionary<string, ProjectTask> Tasks { get; init; } = new Dictionary<string, ProjectTask>();

    /// <summary>The <c>tags</c> member of <c>Project</c>.</summary>
    public IReadOnlyList<string> Tags { get; init; } = [];

    /// <summary>Stack is the stack recorded in the project's manifest, if any.</summary>
    public string Stack { get; init; } = string.Empty;

    /// <summary>Settings are plugins' settings for this project from smith.toml, by plugin name: [projects.&lt;project&gt;.settings.&lt;name&gt;] (what a recipe's settings became when it created the project), and for a convention its [conventions.&lt;name&gt;] settings and the project's [projects.&lt;project&gt;.&lt;name&gt;] on top. Set by the host; a plugin reads its own entry.</summary>
    public IReadOnlyDictionary<string, JsonMap> Settings { get; init; } = new Dictionary<string, JsonMap>();

    /// <summary>Shape is the dialect of the project: named facts about how it is made ("build.tool": "esbuild", "test.runner": "@swc/jest", "exports.target": "dist"), each a short string, read from the manifest and files the plugin already reads in discovery. The host counts the shapes of the projects of one kind and language to let a new project follow what they do, and knows no key itself. Nil when the plugin does not describe shapes.</summary>
    public IReadOnlyDictionary<string, string> Shape { get; init; } = new Dictionary<string, string>();

    /// <summary>Registries are the private registries the project installs from and publishes to, from smith.toml [registries]; nil means the public ones. Set by the host.</summary>
    public Registries? Registries { get; init; }

    /// <summary>ReleaseAssets is what an app's release builds, from smith.toml [projects.&lt;project&gt;.release]: the platforms and file names, so a plugin can check (doctor) and prepare (CI) for them. Nil for a project that has no release files. Set by the host.</summary>
    public AssetSpec? ReleaseAssets { get; init; }

    /// <summary>Facts are the shared facts that hold for the project, merged by the host, narrowest scope first: [projects.&lt;name&gt;.facts], then [facts], then the defaults plugins published through Contribution.Facts. A key that is absent was set by no one: the plugin uses its own default. A request made before every plugin has contributed carries the smith.toml facts and the defaults published so far. Set by the host; read only.</summary>
    public JsonMap Facts { get; init; } = new();

    /// <inheritdoc />
    public static Project Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new Project
        {
            Name = StringValue(Member(map, "name"), Join(path, "name")),
            Root = StringValue(Member(map, "root"), Join(path, "root")),
            Language = StringValue(Member(map, "language"), Join(path, "language")),
            Kind = ProjectKind.Read(Member(map, "kind"), Join(path, "kind")),
            Exports = ListOf(Member(map, "exports"), Join(path, "exports"), StringValue),
            Imports = ListOf(Member(map, "imports"), Join(path, "imports"), StringValue),
            Version = StringValue(Member(map, "version"), Join(path, "version")),
            Toolchain = StringValue(Member(map, "toolchain"), Join(path, "toolchain")),
            PublishTo = StringValue(Member(map, "publishTo"), Join(path, "publishTo")),
            Description = StringValue(Member(map, "description"), Join(path, "description")),
            TagPrefix = StringValue(Member(map, "tagPrefix"), Join(path, "tagPrefix")),
            Tasks = MapOf(Member(map, "tasks"), Join(path, "tasks"), ProjectTask.Read),
            Tags = ListOf(Member(map, "tags"), Join(path, "tags"), StringValue),
            Stack = StringValue(Member(map, "stack"), Join(path, "stack")),
            Settings = MapOf(Member(map, "settings"), Join(path, "settings"), ObjectOf),
            Shape = MapOf(Member(map, "shape"), Join(path, "shape"), StringValue),
            Registries = OptionalStruct<Registries>(Member(map, "registries"), Join(path, "registries")),
            ReleaseAssets = OptionalStruct<AssetSpec>(Member(map, "releaseAssets"), Join(path, "releaseAssets")),
            Facts = ObjectOf(Member(map, "facts"), Join(path, "facts")),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        writer.Property("name");
        writer.String(Name);
        writer.Property("root");
        writer.String(Root);
        writer.Property("language");
        writer.String(Language);
        writer.Property("kind");
        Kind.Write(writer);
        if (Exports is { Count: > 0 })
        {
            writer.Property("exports");
            MessageWritingAlgorithm.List(writer, Exports, (builder1, item1) => builder1.String(item1));
        }
        if (Imports is { Count: > 0 })
        {
            writer.Property("imports");
            MessageWritingAlgorithm.List(writer, Imports, (builder1, item1) => builder1.String(item1));
        }
        if (Version.Length > 0)
        {
            writer.Property("version");
            writer.String(Version);
        }
        if (Toolchain.Length > 0)
        {
            writer.Property("toolchain");
            writer.String(Toolchain);
        }
        if (PublishTo.Length > 0)
        {
            writer.Property("publishTo");
            writer.String(PublishTo);
        }
        if (Description.Length > 0)
        {
            writer.Property("description");
            writer.String(Description);
        }
        if (TagPrefix.Length > 0)
        {
            writer.Property("tagPrefix");
            writer.String(TagPrefix);
        }
        if (Tasks is { Count: > 0 })
        {
            writer.Property("tasks");
            MessageWritingAlgorithm.Map(writer, Tasks, (builder1, member1) => member1.Write(builder1));
        }
        if (Tags is { Count: > 0 })
        {
            writer.Property("tags");
            MessageWritingAlgorithm.List(writer, Tags, (builder1, item1) => builder1.String(item1));
        }
        if (Stack.Length > 0)
        {
            writer.Property("stack");
            writer.String(Stack);
        }
        if (Settings is { Count: > 0 })
        {
            writer.Property("settings");
            MessageWritingAlgorithm.Map(writer, Settings, (builder1, member1) => builder1.Any(member1));
        }
        if (Shape is { Count: > 0 })
        {
            writer.Property("shape");
            MessageWritingAlgorithm.Map(writer, Shape, (builder1, member1) => builder1.String(member1));
        }
        if (Registries is not null)
        {
            writer.Property("registries");
            Registries.Write(writer);
        }
        if (ReleaseAssets is not null)
        {
            writer.Property("releaseAssets");
            ReleaseAssets.Write(writer);
        }
        if (Facts is { Count: > 0 })
        {
            writer.Property("facts");
            writer.Any(Facts);
        }
        writer.EndObject();
    }
}

/// <summary>ProjectKind is the universal kind vocabulary.</summary>
/// <remarks>
/// <para>Project kinds. An app is deployed, never published; a lib is internal and never published; a package is published.</para>
/// </remarks>
/// <remarks>
/// <para>A string, not a closed set: a newer protocol may add values, and one that is not listed here is kept as it came.</para>
/// </remarks>
public readonly record struct ProjectKind : IProtocolValue<ProjectKind>
{
    private readonly string? _value;

    /// <summary>A project kind given as text.</summary>
    /// <param name="value">The text.</param>
    public ProjectKind(string value)
    {
        _value = value;
    }

    /// <summary>The text of the value: empty for the default one.</summary>
    public string Value => _value ?? string.Empty;

    /// <summary>Whether the value is empty, which is what an absent member reads as.</summary>
    public bool IsEmpty => Value.Length == 0;

    /// <summary>The value <c>app</c>.</summary>
    public static ProjectKind App { get; } = new("app");

    /// <summary>The value <c>lib</c>.</summary>
    public static ProjectKind Lib { get; } = new("lib");

    /// <summary>The value <c>package</c>.</summary>
    public static ProjectKind Package { get; } = new("package");

    /// <summary>A ProjectKind from text.</summary>
    /// <param name="value">The text.</param>
    public static implicit operator ProjectKind(string value) => new(value);

    /// <summary>The text of a ProjectKind.</summary>
    /// <param name="value">The value.</param>
    public static implicit operator string(ProjectKind value) => value.Value;

    /// <inheritdoc />
    public static ProjectKind Read(JsonAny? value, string path) => new(MessageReadingAlgorithm.StringValue(value, path));

    /// <inheritdoc />
    public void Write(JsonBuilder writer) => writer.String(Value);

    /// <summary>Whether another value has the same text.</summary>
    /// <param name="other">The other value.</param>
    /// <returns>Whether they are equal.</returns>
    public bool Equals(ProjectKind other) => string.Equals(Value, other.Value, StringComparison.Ordinal);

    /// <inheritdoc />
    public override int GetHashCode() => StringComparer.Ordinal.GetHashCode(Value);

    /// <inheritdoc />
    public override string ToString() => Value;
}

/// <summary>PublishParams asks a plugin to publish one project at one version.</summary>
public sealed record PublishParams : IProtocolValue<PublishParams>
{
    /// <summary>The <c>project</c> member of <c>PublishParams</c>.</summary>
    public required Project Project { get; init; }

    /// <summary>The <c>version</c> member of <c>PublishParams</c>.</summary>
    public required string Version { get; init; }

    /// <summary>The <c>dryRun</c> member of <c>PublishParams</c>.</summary>
    public bool DryRun { get; init; }

    /// <summary>Assets, when set, asks the plugin to build the files attached to the release (an app's per-platform binaries) instead of publishing to a registry.</summary>
    public AssetSpec? Assets { get; init; }

    /// <summary>Platform, when set, is the "os/arch" (Go's spelling) of the runner a native project is published from: each native job publishes its own platform's build (a VS Code extension's target) and nothing else.</summary>
    public string Platform { get; init; } = string.Empty;

    /// <summary>Tagged says the publish runs on the project's own tag, in the run the registry trusts (pub.dev's automated publishing); a registry that takes a package only from such a run is published to only then.</summary>
    public bool Tagged { get; init; }

    /// <summary>Commit is the full hash of the commit being released, and Branch the release branch, for a plugin that tags what it publishes with them (a container image's sha-&lt;short&gt; and branch tags). Empty when unknown.</summary>
    public string Commit { get; init; } = string.Empty;

    /// <summary>The <c>branch</c> member of <c>PublishParams</c>.</summary>
    public string Branch { get; init; } = string.Empty;

    /// <summary>Tag is the name of the release channel the version belongs to (npm's dist-tag "beta"). When set, the plugin publishes under it and leaves the registry's stable pointer where it is, or ignores it when its registry has no such pointer. Only sent to a plugin with the channels capability.</summary>
    public string Tag { get; init; } = string.Empty;

    /// <inheritdoc />
    public static PublishParams Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new PublishParams
        {
            Project = Project.Read(Member(map, "project"), Join(path, "project")),
            Version = StringValue(Member(map, "version"), Join(path, "version")),
            DryRun = BooleanValue(Member(map, "dryRun"), Join(path, "dryRun")),
            Assets = OptionalStruct<AssetSpec>(Member(map, "assets"), Join(path, "assets")),
            Platform = StringValue(Member(map, "platform"), Join(path, "platform")),
            Tagged = BooleanValue(Member(map, "tagged"), Join(path, "tagged")),
            Commit = StringValue(Member(map, "commit"), Join(path, "commit")),
            Branch = StringValue(Member(map, "branch"), Join(path, "branch")),
            Tag = StringValue(Member(map, "tag"), Join(path, "tag")),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        writer.Property("project");
        Project.Write(writer);
        writer.Property("version");
        writer.String(Version);
        if (DryRun)
        {
            writer.Property("dryRun");
            writer.Boolean(DryRun);
        }
        if (Assets is not null)
        {
            writer.Property("assets");
            Assets.Write(writer);
        }
        if (Platform.Length > 0)
        {
            writer.Property("platform");
            writer.String(Platform);
        }
        if (Tagged)
        {
            writer.Property("tagged");
            writer.Boolean(Tagged);
        }
        if (Commit.Length > 0)
        {
            writer.Property("commit");
            writer.String(Commit);
        }
        if (Branch.Length > 0)
        {
            writer.Property("branch");
            writer.String(Branch);
        }
        if (Tag.Length > 0)
        {
            writer.Property("tag");
            writer.String(Tag);
        }
        writer.EndObject();
    }
}

/// <summary>PublishResult reports what happened. Skipped with a reason is a success: an already-published version makes a re-run safe.</summary>
public sealed record PublishResult : IProtocolValue<PublishResult>
{
    /// <summary>The <c>published</c> member of <c>PublishResult</c>.</summary>
    public bool Published { get; init; }

    /// <summary>The <c>skipped</c> member of <c>PublishResult</c>.</summary>
    public string Skipped { get; init; } = string.Empty;

    /// <summary>The <c>registry</c> member of <c>PublishResult</c>.</summary>
    public string Registry { get; init; } = string.Empty;

    /// <summary>Assets are the workspace-relative files built for the release, in upload order; in a dry run, the files that would be built.</summary>
    public IReadOnlyList<string> Assets { get; init; } = [];

    /// <summary>AssetPlatforms maps each archive among Assets to the "os/arch" it was built for, so the host can describe them (package manager manifests).</summary>
    public IReadOnlyDictionary<string, string> AssetPlatforms { get; init; } = new Dictionary<string, string>();

    /// <summary>Binary is the executable's name inside each archive, without ".exe".</summary>
    public string Binary { get; init; } = string.Empty;

    /// <summary>Images are the container images pushed, one per registry, for a deploy step or a GitOps manifest to refer to by digest.</summary>
    public IReadOnlyList<PublishedImage> Images { get; init; } = [];

    /// <inheritdoc />
    public static PublishResult Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new PublishResult
        {
            Published = BooleanValue(Member(map, "published"), Join(path, "published")),
            Skipped = StringValue(Member(map, "skipped"), Join(path, "skipped")),
            Registry = StringValue(Member(map, "registry"), Join(path, "registry")),
            Assets = ListOf(Member(map, "assets"), Join(path, "assets"), StringValue),
            AssetPlatforms = MapOf(Member(map, "assetPlatforms"), Join(path, "assetPlatforms"), StringValue),
            Binary = StringValue(Member(map, "binary"), Join(path, "binary")),
            Images = ListOf(Member(map, "images"), Join(path, "images"), PublishedImage.Read),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        writer.Property("published");
        writer.Boolean(Published);
        if (Skipped.Length > 0)
        {
            writer.Property("skipped");
            writer.String(Skipped);
        }
        if (Registry.Length > 0)
        {
            writer.Property("registry");
            writer.String(Registry);
        }
        if (Assets is { Count: > 0 })
        {
            writer.Property("assets");
            MessageWritingAlgorithm.List(writer, Assets, (builder1, item1) => builder1.String(item1));
        }
        if (AssetPlatforms is { Count: > 0 })
        {
            writer.Property("assetPlatforms");
            MessageWritingAlgorithm.Map(writer, AssetPlatforms, (builder1, member1) => builder1.String(member1));
        }
        if (Binary.Length > 0)
        {
            writer.Property("binary");
            writer.String(Binary);
        }
        if (Images is { Count: > 0 })
        {
            writer.Property("images");
            MessageWritingAlgorithm.List(writer, Images, (builder1, item1) => item1.Write(builder1));
        }
        writer.EndObject();
    }
}

/// <summary>PublishedImage is one container image a release pushed.</summary>
public sealed record PublishedImage : IProtocolValue<PublishedImage>
{
    /// <summary>Reference is the image without a tag: ghcr.io/acme/api.</summary>
    public required string Reference { get; init; }

    /// <summary>Tags are the tags pushed, in the order they were.</summary>
    public IReadOnlyList<string> Tags { get; init; } = [];

    /// <summary>Digest is the manifest digest the registry holds ("sha256:..."); empty when it could not be read.</summary>
    public string Digest { get; init; } = string.Empty;

    /// <inheritdoc />
    public static PublishedImage Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new PublishedImage
        {
            Reference = StringValue(Member(map, "reference"), Join(path, "reference")),
            Tags = ListOf(Member(map, "tags"), Join(path, "tags"), StringValue),
            Digest = StringValue(Member(map, "digest"), Join(path, "digest")),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        writer.Property("reference");
        writer.String(Reference);
        writer.Property("tags");
        MessageWritingAlgorithm.List(writer, Tags, (builder1, item1) => builder1.String(item1));
        if (Digest.Length > 0)
        {
            writer.Property("digest");
            writer.String(Digest);
        }
        writer.EndObject();
    }
}

