/// <summary>PublishedResult is the newest version the registry has of a project.</summary>
public sealed record PublishedResult : IProtocolValue<PublishedResult>
{
    /// <summary>Version is empty when the registry does not know the project: its first release is still to come.</summary>
    public string Version { get; init; } = string.Empty;

    /// <summary>Registry names where the plugin looked, for messages.</summary>
    public string Registry { get; init; } = string.Empty;

    /// <summary>Unreachable is true when the registry could not be asked (offline, an error), so nothing can be concluded; Detail says why.</summary>
    public bool Unreachable { get; init; }

    /// <summary>The <c>detail</c> member of <c>PublishedResult</c>.</summary>
    public string Detail { get; init; } = string.Empty;

    /// <inheritdoc />
    public static PublishedResult Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new PublishedResult
        {
            Version = StringValue(Member(map, "version"), Join(path, "version")),
            Registry = StringValue(Member(map, "registry"), Join(path, "registry")),
            Unreachable = BooleanValue(Member(map, "unreachable"), Join(path, "unreachable")),
            Detail = StringValue(Member(map, "detail"), Join(path, "detail")),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        if (Version.Length > 0)
        {
            writer.Property("version");
            writer.String(Version);
        }
        if (Registry.Length > 0)
        {
            writer.Property("registry");
            writer.String(Registry);
        }
        if (Unreachable)
        {
            writer.Property("unreachable");
            writer.Boolean(Unreachable);
        }
        if (Detail.Length > 0)
        {
            writer.Property("detail");
            writer.String(Detail);
        }
        writer.EndObject();
    }
}

/// <summary>Registries are the registries a project uses, set by the host from smith.toml: Install is where the workspace installs packages from, Publish where the project is published. Nil, or a nil member, means the public registry, as before.</summary>
public sealed record Registries : IProtocolValue<Registries>
{
    /// <summary>The <c>install</c> member of <c>Registries</c>.</summary>
    public Registry? Install { get; init; }

    /// <summary>The <c>publish</c> member of <c>Registries</c>.</summary>
    public Registry? Publish { get; init; }

