/// <summary>Role is a part a plugin plays in a project's make-up: its level. Some levels are exclusive (one plugin per project, or per slot) and the others additive (any number, and they only add).</summary>
/// <remarks>
/// <para>A string, not a closed set: a newer protocol may add values, and one that is not listed here is kept as it came.</para>
/// </remarks>
public readonly record struct Role : IProtocolValue<Role>
{
    private readonly string? _value;

    /// <summary>A role given as text.</summary>
    /// <param name="value">The text.</param>
    public Role(string value)
    {
        _value = value;
    }

    /// <summary>The text of the value: empty for the default one.</summary>
    public string Value => _value ?? string.Empty;

    /// <summary>Whether the value is empty, which is what an absent member reads as.</summary>
    public bool IsEmpty => Value.Length == 0;

    /// <summary>Finds projects from manifests, turns imports into graph edges, writes versions and publishes.</summary>
    public static Role Language { get; } = new("language");

    /// <summary>Decides how a project builds, tests and lints.</summary>
    public static Role Toolchain { get; } = new("toolchain");

    /// <summary>Checks layout and code rules.</summary>
    public static Role Structure { get; } = new("structure");

    /// <summary>Writes a new project's starter files.</summary>
    public static Role Scaffold { get; } = new("scaffold");

    /// <summary>Adds pipeline steps and deploy targets.</summary>
    public static Role Deploy { get; } = new("deploy");

    /// <summary>A Role from text.</summary>
    /// <param name="value">The text.</param>
    public static implicit operator Role(string value) => new(value);

    /// <summary>The text of a Role.</summary>
    /// <param name="value">The value.</param>
    public static implicit operator string(Role value) => value.Value;

    /// <inheritdoc />
    public static Role Read(JsonAny? value, string path) => new(MessageReadingAlgorithm.StringValue(value, path));

    /// <inheritdoc />
    public void Write(JsonBuilder writer) => writer.String(Value);

    /// <summary>Whether another value has the same text.</summary>
    /// <param name="other">The other value.</param>
    /// <returns>Whether they are equal.</returns>
    public bool Equals(Role other) => string.Equals(Value, other.Value, StringComparison.Ordinal);

    /// <inheritdoc />
    public override int GetHashCode() => StringComparer.Ordinal.GetHashCode(Value);

    /// <inheritdoc />
    public override string ToString() => Value;
}

