    public string ServeUrl { get; init; } = string.Empty;

    /// <summary>ServeTimeout is how long to wait for ServeURL, as a Go duration ("60s"); empty means 60s.</summary>
    public string ServeTimeout { get; init; } = string.Empty;

    /// <inheritdoc />
    public static ProjectTask Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new ProjectTask
        {
            Command = ListOf(Member(map, "command"), Join(path, "command"), StringValue),
            Cwd = StringValue(Member(map, "cwd"), Join(path, "cwd")),
            Env = MapOf(Member(map, "env"), Join(path, "env"), StringValue),
            Inputs = ListOf(Member(map, "inputs"), Join(path, "inputs"), StringValue),
            Outputs = ListOf(Member(map, "outputs"), Join(path, "outputs"), StringValue),
            DependsOn = ListOf(Member(map, "dependsOn"), Join(path, "dependsOn"), StringValue),
            Cache = BooleanValue(Member(map, "cache"), Join(path, "cache")),
            Description = StringValue(Member(map, "description"), Join(path, "description")),
            Verify = BooleanValue(Member(map, "verify"), Join(path, "verify")),
            Serve = StringValue(Member(map, "serve"), Join(path, "serve")),
            ServeUrl = StringValue(Member(map, "serveUrl"), Join(path, "serveUrl")),
            ServeTimeout = StringValue(Member(map, "serveTimeout"), Join(path, "serveTimeout")),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        writer.Property("command");
        MessageWritingAlgorithm.List(writer, Command, (builder1, item1) => builder1.String(item1));
        if (Cwd.Length > 0)
        {
            writer.Property("cwd");
            writer.String(Cwd);
        }
        if (Env is { Count: > 0 })
        {
            writer.Property("env");
            MessageWritingAlgorithm.Map(writer, Env, (builder1, member1) => builder1.String(member1));
        }
        if (Inputs is { Count: > 0 })
        {
            writer.Property("inputs");
            MessageWritingAlgorithm.List(writer, Inputs, (builder1, item1) => builder1.String(item1));
        }
        if (Outputs is { Count: > 0 })
        {
            writer.Property("outputs");
            MessageWritingAlgorithm.List(writer, Outputs, (builder1, item1) => builder1.String(item1));
        }
        if (DependsOn is { Count: > 0 })
        {
            writer.Property("dependsOn");
            MessageWritingAlgorithm.List(writer, DependsOn, (builder1, item1) => builder1.String(item1));
        }
        if (Cache)
        {
            writer.Property("cache");
            writer.Boolean(Cache);
        }
        if (Description.Length > 0)
        {
            writer.Property("description");
            writer.String(Description);
        }
        if (Verify)
        {
            writer.Property("verify");
            writer.Boolean(Verify);
        }
        if (Serve.Length > 0)
        {
            writer.Property("serve");
            writer.String(Serve);
        }
        if (ServeUrl.Length > 0)
        {
            writer.Property("serveUrl");
            writer.String(ServeUrl);
        }
        if (ServeTimeout.Length > 0)
        {
            writer.Property("serveTimeout");
            writer.String(ServeTimeout);
        }
        writer.EndObject();
    }
}

/// <summary>ToolPin is a tool the plugin installs at a pinned version (in CI, the dev container, the venv) against the newest release; informational.</summary>
public sealed record ToolPin : IProtocolValue<ToolPin>
{
    /// <summary>The <c>name</c> member of <c>ToolPin</c>.</summary>
    public required string Name { get; init; }

    /// <summary>The <c>pinned</c> member of <c>ToolPin</c>.</summary>
    public required string Pinned { get; init; }

    /// <summary>Latest is empty when its release feed could not be reached.</summary>
    public string Latest { get; init; } = string.Empty;

    /// <summary>Newer is true when Latest is a release the pin does not cover.</summary>
    public bool Newer { get; init; }

    /// <inheritdoc />
    public static ToolPin Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new ToolPin
        {
            Name = StringValue(Member(map, "name"), Join(path, "name")),
            Pinned = StringValue(Member(map, "pinned"), Join(path, "pinned")),
            Latest = StringValue(Member(map, "latest"), Join(path, "latest")),
            Newer = BooleanValue(Member(map, "newer"), Join(path, "newer")),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        writer.Property("name");
        writer.String(Name);
        writer.Property("pinned");
        writer.String(Pinned);
        if (Latest.Length > 0)
        {
            writer.Property("latest");
            writer.String(Latest);
        }
        if (Newer)
        {
            writer.Property("newer");
            writer.Boolean(Newer);
        }
        writer.EndObject();
    }
}

/// <summary>Toolchain is a runtime the pipeline must install, and how. Plugins asking for the same name share one setup step (the first plugin's).</summary>
public sealed record Toolchain : IProtocolValue<Toolchain>
{
    /// <summary>The <c>name</c> member of <c>Toolchain</c>.</summary>
    public required string Name { get; init; }

    /// <summary>The <c>version</c> member of <c>Toolchain</c>.</summary>
    public required string Version { get; init; }

    /// <summary>GitHub is the GitHub Actions step that installs it (an action).</summary>
    public ActionStep? Github { get; init; }

    /// <summary>Azure is the Azure Pipelines step that installs it (a task).</summary>
    public ActionStep? Azure { get; init; }

    /// <summary>Install is a shell command that installs it, run on a provider the plugin gives no native step for.</summary>
    public string Install { get; init; } = string.Empty;

    /// <summary>Devcontainer is the dev container feature that installs it at the same version, so the editor's container matches CI.</summary>
    public DevcontainerFeature? Devcontainer { get; init; }

    /// <inheritdoc />
    public static Toolchain Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new Toolchain
        {
            Name = StringValue(Member(map, "name"), Join(path, "name")),
            Version = StringValue(Member(map, "version"), Join(path, "version")),
            Github = OptionalStruct<ActionStep>(Member(map, "github"), Join(path, "github")),
            Azure = OptionalStruct<ActionStep>(Member(map, "azure"), Join(path, "azure")),
            Install = StringValue(Member(map, "install"), Join(path, "install")),
            Devcontainer = OptionalStruct<DevcontainerFeature>(Member(map, "devcontainer"), Join(path, "devcontainer")),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        writer.Property("name");
        writer.String(Name);
        writer.Property("version");
        writer.String(Version);
        if (Github is not null)
        {
            writer.Property("github");
            Github.Write(writer);
        }
        if (Azure is not null)
        {
            writer.Property("azure");
            Azure.Write(writer);
        }
        if (Install.Length > 0)
        {
            writer.Property("install");
            writer.String(Install);
        }
        if (Devcontainer is not null)
        {
            writer.Property("devcontainer");
            Devcontainer.Write(writer);
        }
        writer.EndObject();
    }
}

