    /// <summary>The <c>version</c> member of <c>VersionParams</c>.</summary>
    public required string Version { get; init; }

    /// <summary>Dependencies maps exported identifiers of other workspace projects to their new versions, so the plugin can update dependency ranges.</summary>
    public IReadOnlyDictionary<string, string> Dependencies { get; init; } = new Dictionary<string, string>();

    /// <summary>The <c>dryRun</c> member of <c>VersionParams</c>.</summary>
    public bool DryRun { get; init; }

    /// <inheritdoc />
    public static VersionParams Read(JsonAny? value, string path)
    {
        var map = ObjectOf(value, path);
        return new VersionParams
        {
            Project = Project.Read(Member(map, "project"), Join(path, "project")),
            Version = StringValue(Member(map, "version"), Join(path, "version")),
            Dependencies = MapOf(Member(map, "dependencies"), Join(path, "dependencies"), StringValue),
            DryRun = BooleanValue(Member(map, "dryRun"), Join(path, "dryRun")),
        };
    }

    /// <inheritdoc />
    public void Write(JsonBuilder writer)
    {
        writer.BeginObject();
        writer.Property("project");
        Project.Write(writer);
        writer.Property("version");
        writer.String(Version);
        if (Dependencies is { Count: > 0 })
        {
            writer.Property("dependencies");
            MessageWritingAlgorithm.Map(writer, Dependencies, (builder1, member1) => builder1.String(member1));
        }
        if (DryRun)
        {
            writer.Property("dryRun");
            writer.Boolean(DryRun);
        }
        writer.EndObject();
    }
}

