/// <summary>What a plugin says about itself: the <c>initialize</c> result without the members the serve loop fills in, <c>protocolVersion</c> and <c>capabilities</c> (derived from the interfaces the plugin implements).</summary>
public sealed record PluginDescription
{
    /// <summary>The <c>plugin</c> member of <c>PluginDescription</c>.</summary>
    public required Peer Plugin { get; init; }

    /// <summary>The <c>kind</c> member of <c>PluginDescription</c>.</summary>
    public required PluginKind Kind { get; init; }

    /// <summary>Concurrency is how many requests the plugin can work on at the same time; the host never has more in flight. Absent or 0 means 1, which is what every plugin that says nothing does: the host sends the next request only after the previous one is answered. N above 1 allows that many, and ConcurrencyUnlimited (-1) leaves the number to the host. Any other negative value is invalid and read as 1.</summary>
    public long Concurrency { get; init; }

    /// <summary>Languages are the values a user passes to --lang to reach this plugin.</summary>
    public IReadOnlyList<string> Languages { get; init; } = [];

    /// <summary>Manifests are file base names (package.json, go.mod), or patterns of them (*.csproj), whose presence in a directory may make it a project of this plugin.</summary>
    public IReadOnlyList<string> Manifests { get; init; } = [];

    /// <summary>Roles are the levels the plugin can be chosen for in a project's make-up (a stack, a recipe). Empty means the default of its kind (see DefaultRoles). A role is a level: there is no separate level field, because one plugin can play several (a scaffold that is also a toolchain).</summary>
    public IReadOnlyList<Role> Roles { get; init; } = [];

    /// <summary>Provides are the slots a toolchain plugin fills: the task names it owns ("test" for a test runner). A slot is exclusive: two plugins of one project may not provide the same task.</summary>
    public IReadOnlyList<string> Provides { get; init; } = [];

    /// <summary>Requires are plugins that must also be in the project for this one to work: a Node toolchain requires the node language plugin.</summary>
    public IReadOnlyList<PluginRef> Requires { get; init; } = [];

    /// <summary>Conflicts are plugins that must not be in the same project.</summary>
    public IReadOnlyList<PluginRef> Conflicts { get; init; } = [];

    /// <summary>Stacks are ready-made stacks the plugin publishes.</summary>
    public IReadOnlyList<Stack> Stacks { get; init; } = [];

    /// <summary>Kinds are the project kinds the plugin can scaffold with generate. Absent or empty means all three (app, lib and package): what every plugin that says nothing does. A plugin that scaffolds only some, such as an app, lists them, so the host offers and the conformance suite asks for just those.</summary>
    public IReadOnlyList<ProjectKind> Kinds { get; init; } = [];

    /// <summary>Follows are the shape keys (see Project.Shape) the plugin applies when it generates a project with GenerateParams.Shape. Where siblings split on a key, the host asks the person only for a key that a plugin of the stack follows. Absent means the plugin follows none.</summary>
    public IReadOnlyList<string> Follows { get; init; } = [];

    /// <summary>Choices are the options on an axis (framework, test, style) the plugin owns. The host lists them (smith choices) and checks a selection of them (smith add --with). Absent means the plugin owns none.</summary>
    public IReadOnlyList<Choice> Choices { get; init; } = [];

    /// <summary>The <c>initialize</c> result for this description.</summary>
    /// <param name="capabilities">The capabilities derived from the plugin.</param>
    /// <returns>The result the serve loop answers.</returns>
    public InitializeResult ToInitializeResult(Capabilities capabilities) =>
        new()
        {
            ProtocolVersion = ProtocolInfo.Version,
            Capabilities = capabilities,
            Plugin = Plugin,
            Kind = Kind,
            Concurrency = Concurrency,
            Languages = Languages,
            Manifests = Manifests,
            Roles = Roles,
            Provides = Provides,
            Requires = Requires,
            Conflicts = Conflicts,
            Stacks = Stacks,
            Kinds = Kinds,
            Follows = Follows,
            Choices = Choices,
        };
}
